# ORACLE SYSTEMS LLC // PHASE 31.1 STORE 3D WEBGL + GITHUB AUTH HOTFIX (PS 5.1)
# Fixes:
#  1) Self-hosts three.min.js locally (zero CDN failure) & fixes GLSL smoothstep
#     edge-order bug on Windows Edge ANGLE/D3D11 + removes heavy FBO composer
#  2) Renders Living 3D Cards face-up immediately on load + CSS 3D auto-fallback
#  3) Fixes Git Credential Manager paging-file crash & pushes cleanly to GitHub
# ==============================================================================
$ErrorActionPreference = "Continue"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$ProjectDir = "C:\Users\toome\Desktop\SovereignCore"
Set-Location $ProjectDir

# Reclaim RAM first so GitCredentialManager & Browser GPU have clean headroom
if (Test-Path "$ProjectDir\optimize_ram_and_boot.ps1") { & "$ProjectDir\optimize_ram_and_boot.ps1" -TrimNow }

function Write-B64File([string]$Path, [string]$B64) {
    $bytes = [System.Convert]::FromBase64String($B64)
    [System.IO.File]::WriteAllBytes($Path, $bytes)
    Write-Host "  [WROTE] $Path ($($bytes.Length) bytes)" -ForegroundColor DarkCyan
}

