python "$ProjectDir\Modules\phase22_fix_webgl.py"

Write-Host "`n>>> [2/3] Verifying 100% Revenue Readiness Scorecard & Tunnel..." -ForegroundColor Cyan
if (Test-Path "$ProjectDir\audit_revenue_gaps.ps1") { & "$ProjectDir\audit_revenue_gaps.ps1" }

Write-Host "`n>>> [3/3] Repairing GitHub Credential Manager & Pushing to origin/main..." -ForegroundColor Cyan
git config --global user.name "Toomer1980"
git config --global user.email "Toomer1980@gmail.com"
git config --global credential.helper manager

$SafeFiles = @(
    "Deploy_Phase_31_Living3D.ps1","Fix_Store3D_and_GitHub.ps1","sovereign_daemon.py",
    "static/oracle_webgl_store.html","Modules/phase22_fix_webgl.py","Modules/qa_deep_audit.py",
    "Modules/voice_master_deck.py","Modules/render_cinema_short.py","Modules/render_real_full_reading.py",
    "Modules/sync_youtube_cinema.py"
)
foreach ($sf in $SafeFiles) { if (Test-Path "$ProjectDir\$sf") { git add -- $sf } }
$st = git diff --cached --name-only
if ($st) {
    git commit -m "Phase 31.1 Hotfix: Local Three.js, ANGLE-safe GLSL living-card shader, instant face-up 3D stage & GitHub push fix"
}

$br = (git rev-parse --abbrev-ref HEAD).Trim()
git push -u origin $br
if ($LASTEXITCODE -ne 0) {
    Write-Host "`n[GITHUB NOTE] If Git asked for login or failed due to Windows low paging file:" -ForegroundColor Yellow
    Write-Host "  1) Close extra Edge tabs/Notepad windows to free RAM." -ForegroundColor Yellow
    Write-Host "  2) Re-run: git push -u origin $br  (approve the GitHub browser sign-in if prompted)." -ForegroundColor Yellow
} else {
    Write-Host "[GITHUB PASS] Pushed cleanly to Toomer1980/monday_project ($br)!" -ForegroundColor Green
}

$pub = if (Test-Path "$ProjectDir\config\public_url.txt") { (Get-Content "$ProjectDir\config\public_url.txt" -Raw).Trim() } else { "http://127.0.0.1:8000" }
Start-Process "$pub/store"
Write-Host "`n[HOTFIX COMPLETE] Hit Ctrl+F5 on /store - your 3 living ray-traced cards will now appear face-up immediately!" -ForegroundColor Green
